-- Japan 2025 plan query (read-only).
SELECT '136fb83c77f027186f2e3e107d6122f0' plan_md5, 71 n_plan, * FROM (
WITH p AS (SELECT (e->>0)::int seq, e->>1 cat, e->>2 slug, nullif(e->>3, '') use_vid, e->>4 skey FROM jsonb_array_elements('[[1, "Green Star", "la-paix-1194221", "", "T|green"], [2, "Green Star", "faro-1194154", "", "T|green"], [4, "Green Star", "florilege", "", "T|green"], [5, "Green Star", "daigo", "", "T|green"], [6, "Green Star", "den", "", "T|green"], [7, "Green Star", "crony-1194937", "", "T|green"], [8, "Green Star", "sincere", "", "T|green"], [9, "Green Star", "narisawa", "", "T|green"], [10, "Green Star", "l-effervescence", "", "T|green"], [11, "Green Star", "lature", "", "T|green"], [12, "Green Star", "nol", "", "T|green"], [13, "Three Stars", "kanda", "", "T|3"], [14, "Three Stars", "azabu-kadowaki", "", "T|3"], [15, "Three Stars", "kohaku", "", "T|3"], [16, "Three Stars", "sezanne", "ve_05c8533123", "T|3"], [17, "Three Stars", "harutaka", "", "T|3"], [18, "Three Stars", "l-osier", "", "T|3"], [19, "Three Stars", "kagurazaka-ishikawa", "", "T|3"], [20, "Three Stars", "ryugin-1194232", "", "T|3"], [21, "Three Stars", "l-effervescence", "", "T|3"], [22, "Three Stars", "joel-robuchon-1193981", "", "T|3"], [23, "Three Stars", "quintessence-1193907", "", "T|3"], [24, "Three Stars", "sazenka", "", "T|3"], [26, "Green Star", "shigetsu", "", "K|green"], [27, "Green Star", "la-buche", "", "K|green"], [29, "Green Star", "miyamaso", "", "K|green"], [30, "Green Star", "juu-go", "", "K|green"], [31, "Green Star", "tan", "", "K|green"], [32, "Green Star", "kodaiji-wakuden", "", "K|green"], [33, "Green Star", "muromachi-wakuden", "", "K|green"], [34, "Green Star", "sojiki-nakahigashi", "", "K|green"], [35, "Three Stars", "mizai", "", "K|3"], [36, "Three Stars", "gion-sasaki", "", "K|3"], [37, "Three Stars", "isshisoden-nakamura", "", "K|3"], [38, "Three Stars", "hyotei", "", "K|3"], [39, "Three Stars", "kikunoi-honten", "", "K|3"], [40, "Two Stars", "yusokuryori-mankamero", "", "K|2"], [41, "Two Stars", "sanso-kyoyamato", "", "K|2"], [42, "Two Stars", "ogata", "", "K|2"], [43, "Two Stars", "kyokaiseki-kichisen", "", "K|2"], [44, "Two Stars", "gion-nishikawa", "", "K|2"], [45, "Two Stars", "otagi", "", "K|2"], [46, "Two Stars", "miyamaso", "", "K|2"], [47, "Two Stars", "sumibi-kappo-ifuki", "", "K|2"], [48, "Two Stars", "kenninji-gion-maruyama", "", "K|2"], [49, "Two Stars", "kodaiji-wakuden", "", "K|2"], [50, "Two Stars", "kikunoi-roan", "", "K|2"], [51, "Two Stars", "sojiki-nakahigashi", "", "K|2"], [52, "Two Stars", "kodaiji-jugyuan", "", "K|2"], [53, "Two Stars", "gion-matayoshi", "", "K|2"], [54, "Two Stars", "gion-maruyama", "", "K|2"], [55, "Two Stars", "ryo-sho", "", "K|2"], [76, "Green Star", "terada", "", "O|green"], [77, "Green Star", "kashiwaya-osaka-senriyama", "", "O|green"], [79, "Three Stars", "hajime", "", "O|3"], [80, "Three Stars", "taian", "", "O|3"], [81, "Three Stars", "kashiwaya-osaka-senriyama", "", "O|3"], [82, "Two Stars", "la-cime", "", "O|2"], [83, "Two Stars", "miyamoto", "", "O|2"], [84, "Two Stars", "fujiya-1935", "", "O|2"], [85, "Two Stars", "koryu", "", "O|2"], [86, "Two Stars", "yugen-1193266", "", "O|2"], [87, "Two Stars", "shunsaiten-tsuchiya", "", "O|2"], [88, "Two Stars", "sushi-harasho", "", "O|2"], [89, "Two Stars", "numata", "", "O|2"], [90, "Two Stars", "kahala", "", "O|2"], [91, "Two Stars", "oimatsu-hisano", "", "O|2"], [92, "Two Stars", "tenjimbashi-aoki", "", "O|2"], [113, "Green Star", "da-terra-1197086", "", "N|green"], [114, "Green Star", "sen-1218506", "", "N|green"], [119, "Green Star", "chugokusai-naramachi-kuko", "ve_c0eba7ae71", "N|green"]]'::jsonb) e),
  sl AS (SELECT DISTINCT lower(substring(a.source_url from '/(?:restaurant|restaurante)/([^/?#]+)')) slug, a.venue_id
           FROM awards a JOIN venues v ON v.id = a.venue_id JOIN cities c ON c.id = v.city_id
          WHERE a.source_id = 'michelin' AND a.source_url ~ '/restaurante?/' AND c.country_iso = 'JP'),
  t1 AS (SELECT p.seq, count(*) n, min(sl.venue_id) vid FROM p JOIN sl ON sl.slug = p.slug GROUP BY p.seq),
  r AS (SELECT p.seq, p.cat, p.skey,
          CASE WHEN p.use_vid IS NOT NULL THEN p.use_vid WHEN t1.n = 1 THEN t1.vid END vid,
          CASE WHEN p.use_vid IS NOT NULL THEN 'use' WHEN t1.n = 1 THEN 'card' WHEN t1.n > 1 THEN 'multi' ELSE 'none' END how
        FROM p LEFT JOIN t1 USING (seq))
SELECT
  (SELECT string_agg(how || ':' || cnt, ',' ORDER BY how) FROM (SELECT how, count(*) cnt FROM r GROUP BY how) h) by_how,
  (SELECT md5(string_agg(seq || ':' || coalesce(vid, '-'), ',' ORDER BY seq)) FROM r) seqvid_md5,
  (SELECT count(DISTINCT (vid, cat)) FROM r) distinct_vid_cat,
  (SELECT count(DISTINCT vid) FROM r) distinct_vid,
  (SELECT count(*) FROM r JOIN venues v ON v.id = r.vid JOIN cities c ON c.id = v.city_id WHERE c.country_iso = 'JP') in_jp,
  (SELECT count(*) FROM r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat) existing_n,
  (SELECT count(*) FROM r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat
     AND a.source_url IS NULL AND a.rank IS NULL AND a.distinction IS NULL) existing_clean,
  (SELECT md5(string_agg(a.id::text, ',' ORDER BY a.id)) FROM r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat) existing_ids_md5,
  (SELECT string_agg(a.id::text, ',' ORDER BY a.id) FROM r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025 AND a.category = r.cat) existing_ids,
  (SELECT string_agg(r.seq || '>' || a.id || ':' || a.category, ',' ORDER BY r.seq) FROM r JOIN awards a ON a.venue_id = r.vid AND a.source_id = 'michelin' AND a.year = 2025
     AND a.category <> r.cat AND a.category IN ('Three Stars', 'Two Stars', 'One Star') AND r.cat <> 'Green Star') star_conflicts,
  (SELECT string_agg(cat || ':' || cnt, ',' ORDER BY cat) FROM (SELECT cat, count(*) cnt FROM r GROUP BY cat) c) by_cat,
  (SELECT count(*) FROM r JOIN venues v ON v.id = r.vid WHERE v.status = 'closed') closed_venues,
  (SELECT string_agg(r.seq || ':' || v.name || ':' || c.display, ' ; ' ORDER BY r.seq) FROM r JOIN venues v ON v.id = r.vid JOIN cities c ON c.id = v.city_id WHERE r.how = 'use') use_rows
) q;
